        }
        None
    }

    fn fields(&self) -> Vec<Arc<str>> {
        let mut seen = BTreeSet::new();
        let mut rv = Vec::new();
        for val in &self.0 {
            if let Ok(iter) = val.try_iter() {
                for item in iter {
                    let s: Result<Arc<str>, _> = item.try_into();
                    if let Ok(s) = s {
                        if !seen.contains(&s) {
                            seen.insert(s.clone());
                            rv.push(s);
                        }
                    }
                }
            }
        }
        rv
    }
}

